// Do 1º dia do mês anterior até agora: a Meta ainda ajusta os números dos dias recentes.
const cfg = $input.first().json;
const agora = new Date();
const inicio = Date.UTC(agora.getUTCFullYear(), agora.getUTCMonth() - 1, 1) / 1000;
const fim = Math.floor(agora.getTime() / 1000);
const campos = 'currency,pricing_analytics.start(' + inicio + ').end(' + fim + ').granularity(DAILY).dimensions(["PRICING_CATEGORY","PRICING_TYPE"])';
return [{ json: { waba: String(cfg.waba_id).trim(), inicio, fim, campos, dia_inicio: new Date(inicio * 1000).toISOString().slice(0, 10) } }];

// Uma linha por dia, categoria e tipo (cobrada ou grátis), com volume e custo na moeda da conta.
const r = $input.first().json;
if (!r.pricing_analytics) throw new Error('A Meta não devolveu pricing_analytics. Confira o ID da conta (waba_id) e a permissão do token.');
const moeda = r.currency || null;
const soma = new Map();
for (const bloco of r.pricing_analytics.data || []) {
  for (const p of bloco.data_points || []) {
    const dia = new Date(Number(p.start) * 1000).toISOString().slice(0, 10);
    const categoria = p.pricing_category || 'DESCONHECIDA';
    const tipo = p.pricing_type || 'REGULAR';
    const chave = dia + '|' + categoria + '|' + tipo;
    const l = soma.get(chave) || { dia, categoria, tipo, volume: 0, custo: 0, moeda };
    l.volume += Number(p.volume || 0);
    l.custo += Number(p.cost || 0);
    soma.set(chave, l);
  }
}
const linhas = [...soma.values()];
return [{ json: { linhas: linhas.length, moeda, payload: JSON.stringify(linhas), dia_inicio: $('Montar período').first().json.dia_inicio } }];
